// src/pages/Register.js - User Registration Page
import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { registerUser } from '../api/authAPI';
import { useAuth } from '../context/AuthContext';

const Register = () => {
  const navigate  = useNavigate();
  const { login } = useAuth();

  // ---- Form State ----
  const [formData, setFormData] = useState({ name: '', email: '', password: '' });
  const [confirmPassword, setConfirmPassword] = useState('');

  // ---- UI State ----
  const [error,   setError]   = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const [showPass, setShowPass] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);

  // ---- Handle input change ----
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    setError('');
  };

  // ---- Client-side Validation ----
  const validate = () => {
    const { name, email, password } = formData;

    if (!name.trim() || !email.trim() || !password) {
      return 'All fields are required.';
    }
    if (name.trim().length < 2) {
      return 'Name must be at least 2 characters.';
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      return 'Please enter a valid email address.';
    }
    if (password.length < 6) {
      return 'Password must be at least 6 characters.';
    }
    if (password !== confirmPassword) {
      return 'Passwords do not match.';
    }
    return null; // no errors
  };

  // ---- Form Submit ----
  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    // Validate first
    const validationError = validate();
    if (validationError) {
      setError(validationError);
      return;
    }

    setLoading(true);
    try {
      // Call the register API
      const data = await registerUser(formData);

      // Save token and user to global auth context
      login(data);

      setSuccess('Account created successfully! Redirecting...');

      // Redirect to dashboard after short delay
      setTimeout(() => navigate('/dashboard'), 1500);
    } catch (err) {
      // Handle error response from backend
      const msg = err.response?.data?.message || 'Registration failed. Please try again.';
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  // ---- Password strength indicator ----
  const getStrength = (pass) => {
    if (!pass) return { level: 0, label: '', color: '' };
    if (pass.length < 6) return { level: 1, label: 'Weak', color: '#ef4444' };
    if (pass.length < 10 && !/[A-Z]/.test(pass)) return { level: 2, label: 'Fair', color: '#f59e0b' };
    if (pass.length >= 8 && /[A-Z]/.test(pass) && /[0-9]/.test(pass)) return { level: 4, label: 'Strong', color: '#10b981' };
    return { level: 3, label: 'Good', color: '#06b6d4' };
  };
  const strength = getStrength(formData.password);

  return (
    <div className="auth-page">
      <div className="auth-card">

        {/* ---- Brand Logo ---- */}
        <div className="auth-brand">
          <div className="brand-icon">🔐</div>
          <h1>Create Account</h1>
          <p>Join us today — it's completely free</p>
        </div>

        {/* ---- Error Alert ---- */}
        {error && (
          <div className="alert-custom alert-error mb-3">
            <i className="bi bi-exclamation-circle-fill"></i>
            {error}
          </div>
        )}

        {/* ---- Success Alert ---- */}
        {success && (
          <div className="alert-custom alert-success mb-3">
            <i className="bi bi-check-circle-fill"></i>
            {success}
          </div>
        )}

        {/* ---- Registration Form ---- */}
        <form onSubmit={handleSubmit} noValidate>

          {/* Name Field */}
          <div className="mb-3">
            <label htmlFor="name" className="form-label">Full Name</label>
            <div className="input-group-icon">
              <i className="bi bi-person input-icon"></i>
              <input
                id="name"
                type="text"
                name="name"
                className="form-control"
                placeholder="John Doe"
                value={formData.name}
                onChange={handleChange}
                autoComplete="name"
                required
              />
            </div>
          </div>

          {/* Email Field */}
          <div className="mb-3">
            <label htmlFor="reg-email" className="form-label">Email Address</label>
            <div className="input-group-icon">
              <i className="bi bi-envelope input-icon"></i>
              <input
                id="reg-email"
                type="email"
                name="email"
                className="form-control"
                placeholder="john@example.com"
                value={formData.email}
                onChange={handleChange}
                autoComplete="email"
                required
              />
            </div>
          </div>

          {/* Password Field */}
          <div className="mb-2">
            <label htmlFor="reg-password" className="form-label">Password</label>
            <div className="input-group-icon" style={{ position: 'relative' }}>
              <i className="bi bi-lock input-icon"></i>
              <input
                id="reg-password"
                type={showPass ? 'text' : 'password'}
                name="password"
                className="form-control"
                placeholder="Min. 6 characters"
                value={formData.password}
                onChange={handleChange}
                autoComplete="new-password"
                required
              />
              <button
                type="button"
                className="password-toggle"
                onClick={() => setShowPass(!showPass)}
                aria-label="Toggle password visibility"
              >
                <i className={`bi ${showPass ? 'bi-eye-slash' : 'bi-eye'}`}></i>
              </button>
            </div>

            {/* Password Strength Bar */}
            {formData.password && (
              <div className="mt-2">
                <div style={{ display: 'flex', gap: '4px', marginBottom: '4px' }}>
                  {[1, 2, 3, 4].map((lvl) => (
                    <div
                      key={lvl}
                      style={{
                        flex: 1,
                        height: '4px',
                        borderRadius: '2px',
                        background: lvl <= strength.level ? strength.color : '#334155',
                        transition: 'background 0.3s',
                      }}
                    />
                  ))}
                </div>
                <span style={{ fontSize: '0.75rem', color: strength.color }}>{strength.label}</span>
              </div>
            )}
          </div>

          {/* Confirm Password Field */}
          <div className="mb-4">
            <label htmlFor="confirm-password" className="form-label">Confirm Password</label>
            <div className="input-group-icon" style={{ position: 'relative' }}>
              <i className="bi bi-shield-lock input-icon"></i>
              <input
                id="confirm-password"
                type={showConfirm ? 'text' : 'password'}
                className="form-control"
                placeholder="Re-enter your password"
                value={confirmPassword}
                onChange={(e) => { setConfirmPassword(e.target.value); setError(''); }}
                required
              />
              <button
                type="button"
                className="password-toggle"
                onClick={() => setShowConfirm(!showConfirm)}
                aria-label="Toggle confirm password visibility"
              >
                <i className={`bi ${showConfirm ? 'bi-eye-slash' : 'bi-eye'}`}></i>
              </button>
            </div>
          </div>

          {/* Submit Button */}
          <button
            id="register-btn"
            type="submit"
            className="btn-auth"
            disabled={loading}
          >
            {loading ? (
              <>
                <span
                  className="spinner-border spinner-border-sm me-2"
                  role="status"
                  aria-hidden="true"
                />
                Creating Account...
              </>
            ) : (
              <>
                <i className="bi bi-person-plus me-2"></i>
                Create Account
              </>
            )}
          </button>
        </form>

        {/* ---- Footer Link ---- */}
        <div className="auth-footer">
          Already have an account?{' '}
          <Link to="/login" className="auth-link">
            Sign in here
          </Link>
        </div>
      </div>
    </div>
  );
};

export default Register;
